"""Credential-free, actionable UI errors shared by native and rollout servers."""
import re
import secrets


def clean(message):
    value = str(message or '')[:1200]
    value = re.sub(r'(?i)([a-z][a-z0-9+.-]*://)[^\s/@]+@', r'\1[حذف‌شده]@', value)
    value = re.sub(r'(?i)\b(token|password|secret|authorization|license_key)\s*[:=]\s*[^\s,;]+', r'\1=[حذف‌شده]', value)
    value = re.sub(r'FS-[A-Za-z0-9_-]{20,}', '[کلید حذف‌شده]', value)
    return value[:500]


def response_error(message, status=400, operation='', code=None):
    text = clean(message)
    low = text.lower()
    host = 'hosts/' in operation
    recovery = 'در بخش «میزبان‌ها و کانفیگ‌ها»، عملیات نیمه‌تمام را بررسی کن.' if host else 'در «اتصال و بازیابی»، وضعیت عملیات نیمه‌تمام را بررسی کن.'
    choices = [
        ('license_required', 'اعتبار لایسنس نیاز به بررسی دارد', 'تب «لایسنس» را باز کن و وضعیت اعتبار یا کلید همین محصول را بررسی کن.', 'لایسنس' in text),
        ('csrf_expired', 'اعتبار درخواست پایان یافته است', 'اطلاعات فرم را نگه دار، صفحه را تازه کن و دوباره وارد پنل شو.', 'درخواست منقضی' in text or 'csrf' in low),
        ('origin_mismatch', 'آدرس بازکردن پنل با درخواست یکسان نیست', 'پنل را از آدرس اصلی خودش باز کن؛ درخواست باید از همان دامنه، پورت و HTTPS فرستاده شود.', any(x in low for x in ['مبدأ','مبدا','origin'])),
        ('host_not_allowed', 'این آدرس برای پنل مجاز نیست', 'از همان دامنه یا IP و پورتی استفاده کن که هنگام نصب ثبت شده است.', status == 421 or 'میزبان مجاز' in text or 'دامنه نامعتبر' in text),
        ('login_failed', 'ورود تأیید نشد', 'نام کاربری، رمز و کد دومرحله‌ای پنل ثنایی را بررسی کن.', status == 401 and ('رمز' in text or 'کاربری' in text)),
        ('login_required', 'ورود به پنل لازم است', 'با حساب پنل ثنایی در همین مرورگر وارد شو؛ سپس دوباره اقدام کن.', status == 401),
        ('rate_limited', 'تعداد تلاش‌ها بیش از حد است', 'پنج دقیقه صبر کن و بعد دوباره امتحان کن.', status == 429),
        ('write_unconfirmed', 'ثبت تغییر هنوز تأیید نشده است', 'درخواست را خودکار یا پیاپی تکرار نکن. ' + recovery, any(x in text for x in ['تأیید نشد','ثبت‌نشده','نتیجهٔ Host','بازخوانی تنظیمات'])),
        ('operation_pending', 'یک عملیات نیمه‌تمام وجود دارد', recovery, any(x in text for x in ['نیمه‌تمام','نیمه تمام'])),
        ('stale_revision', 'تنظیمات هم‌زمان تغییر کرده‌اند', 'فهرست را تازه کن و نسخهٔ جدید همین مورد را دوباره باز کن. اطلاعات فرم فعلی پاک نشده است.', status == 409 or any(x in text for x in ['هم‌زمان','تغییر کرده','ویرایش دیگری'])),
        ('port_unavailable', 'پورت انتخابی قابل استفاده نیست', 'یک پورت آزاد بین ۱۰۲۴ تا ۶۰۹۹۹ انتخاب کن؛ آدرس و پورت تکراری نباشد.', 'پورت' in text and any(x in text for x in ['آزاد','اشغال','استفاده'])) ,
        ('engine_missing', 'موتور خروجی هنوز نصب نشده است', 'در «اتصال و بازیابی» وضعیت نصب موتور را بررسی کن؛ یا خروجی SOCKS خودت را انتخاب کن.', 'موتور' in text and any(x in text for x in ['نصب','پیدا'])),
        ('host_address_invalid', 'آدرس ورود Host معتبر نیست', 'فقط دامنه یا IP با پورت اختیاری وارد کن؛ مثلاً example.com:443. پیشوند https://، مسیر وب و رمز را در آدرس Host ننویس.', 'Host' in text and any(x in text for x in ['آدرس','IP','دامنه','رنج'])),
        ('proxy_invalid', 'آدرس خروجی معتبر نیست', 'خروجی SOCKS را با قالب socks5://host:port یا socks5h://host:port وارد کن؛ آدرس، پورت و اطلاعات ورود باید درست باشند.', 'socks' in low or 'پروکسی' in text),
        ('inbound_required', 'اینباند انتخاب‌شده قابل استفاده نیست', 'حداقل یک اینباند مرتبط انتخاب کن و موجودبودن آن را در ثنایی بررسی کن.' if host else 'یک اینباند فعال TCP سازگار انتخاب کن؛ وجود اینباند را در خود ثنایی هم بررسی کن.', 'اینباند' in text),
        ('panel_not_connected', 'اتصال به ثنایی ثبت نشده است', 'در «اتصال و بازیابی» آدرس کامل پنل و توکن Admin آن را ثبت کن.', 'ابتدا اتصال پنل' in text),
        ('metadata_stale', 'اطلاعات اینباندها به‌روز نیست', 'دکمهٔ به‌روزرسانی را بزن. اگر همگام‌سازی انجام نشد، ارتباط افزونه با پنل را بررسی کن؛ ضریب تغییر نکرده است.', 'همگام' in text and any(x in text for x in ['نیاز','نشد','نشده'])),
        ('panel_unavailable', 'ارتباط با ثنایی برقرار نشد', 'فعال‌بودن پنل، آدرس، پورت و اعتبار دسترسی را بررسی کن؛ پس از برقراری ارتباط وضعیت را تازه کن.', status == 503 and 'پنل' in text),
        ('permission_denied', 'دسترسی این عملیات را نداری', 'با حساب مجاز وارد شو؛ دسترسی Admin و مجوز اینباند انتخابی را بررسی کن.', status == 403),
        ('not_found', 'مورد درخواستی پیدا نشد', 'فهرست را تازه کن؛ ممکن است این مورد حذف شده یا آدرس صفحه تغییر کرده باشد.', status == 404),
        ('service_unavailable', 'سرویس مدیریت پاسخ نداد', 'وضعیت سرویس مدیریت و ارتباط سرور را بررسی کن. برای تغییرات ثبت‌نشده، قبل از تکرار وضعیت عملیات را بخوان.', status in (502,503,504)),
        ('internal_error', 'عملیات به خطای داخلی برخورد کرد', 'شناسهٔ خطای زیر را برای پشتیبانی نگه دار. قبل از تکرار، وضعیت عملیات را بررسی کن.', status >= 500),
    ]
    if code == 'upstream_timeout':
        selected = ('upstream_timeout','پاسخ سرویس در زمان لازم دریافت نشد','ممکن است درخواست در سرور هنوز در حال انجام باشد. قبل از ثبت دوباره، وضعیت مسیر یا عملیات نیمه‌تمام را بررسی کن.')
    elif code == 'tls_error':
        selected = ('tls_error','گواهی ارتباط با سرویس معتبر نیست','دامنه، تاریخ گواهی و تنظیمات HTTPS سرویس را بررسی کن؛ اعتبارسنجی گواهی را غیرفعال نکن.')
    else:
        selected = next((item[:3] for item in choices if item[3]), ('validation_failed','اطلاعات یا تنظیمات نیاز به اصلاح دارد','موارد گفته‌شده را در همین فرم اصلاح کن و دوباره ذخیره کن.'))
    return {'error':text or 'عملیات انجام نشد.', 'error_code':selected[0], 'error_title':selected[1], 'error_hint':selected[2], 'error_id':secrets.token_hex(6)}
